// Both MinGW and native MSVC provide a "MSVC"-like environment -- except
// this project's own Bionic-style libc (always compiled with -D__BIONIC__,
// see tools/crt-libcxx-build.py's own common_cmake_args()), which provides
// neither: no _locale_t/_create_locale/_free_locale, no _aligned_malloc,
// none of the other MSVC CRT-specific entry points this macro gates.
#    if !defined(__BIONIC__)
#      define _LIBCPP_MSVCRT_LIKE
#    endif

// Both MinGW and native MSVC provide a "MSVC"-like environment -- except
// this project's own Bionic-style libc (always compiled with -D__BIONIC__,
// see tools/crt-libcxx-build.py's own common_cmake_args()), which provides
// neither: no _locale_t/_create_locale/_free_locale, no _aligned_malloc,
// none of the other MSVC CRT-specific entry points this macro gates.
#    if !defined(__BIONIC__)
#      define _LIBCPP_MSVCRT_LIKE
#    endif

_LIBCPP_BEGIN_NAMESPACE_STD

// This project's own Bionic-style libc (see include/__config's own matching
// _LIBCPP_MSVCRT_LIKE patch/reason for the fuller story) has no MSVC-CRT fd
// model at all, so _get_osfhandle() (needed by __is_windows_terminal()/
// __write_to_windows_console() below) has nothing to call -- fall through
// to the portable __is_posix_terminal() path (isatty(), which this
// project's own libc genuinely implements on every platform including
// Windows, backed by its own internal fd->HANDLE table) by locally
// treating this one file as not-WIN32API for its own print-only dispatch.
// Scope-checked before patching: grepped libcxx/include/format,
// libcxx/include/string and libcxx/include/__format for _LIBCPP_WIN32API --
// zero hits, so nothing else this header transitively pulls in is affected.
#  undef _LIBCPP_WIN32API

#  ifdef _LIBCPP_WIN32API
_LIBCPP_EXPORTED_FROM_ABI bool __is_windows_terminal(FILE* __stream);

#include "filesystem/error.h"

// Matching undef, matching reasoning: see ../include/print's own patch of
// the same name for the full story -- this file's own __is_windows_terminal/
// __write_to_windows_console definitions must stay in lockstep with that
// public header's own dispatch, or the two disagree on which symbols exist
// (a link error, not a compile error). Scope-checked: this is the only
// _LIBCPP_WIN32API-gated code in this file (grepped for real).
#undef _LIBCPP_WIN32API

#if defined(_LIBCPP_WIN32API)
